import { inferRevealVariant } from './inferReveal.js';
import { prefersReducedMotion } from './motionPrefs.js';

const SELECTOR = [
  'h1',
  'h2',
  'h3',
  '.mmc-section-eyebrow',
  '.mmc-eyebrow',
  '.mmc-label',
  '.section-title',
  '.mmc-pricing-head',
  '.mmc-price-card',
  '.mmc-auth-card',
  '.mmc-blog-toolbar',
  '.mmc-faq-item',
  '.mmc-ca-what-grid > *',
  '.mmc-ca-video-card',
  '.mmc-pred-hero-inner',
  '.mmc-predictor-layout > *',
  '.mmc-cmp-hero-inner',
  '.mmc-enquiry-form',
  '.mmc-enquiry-container',
  '.mmc-dash-stat',
  '.mmc-svc-banner h1',
  '.mmc-svc-banner > p',
  '.mmc-svc-banner .mmc-why-cta',
  '.mmc-svc-cta',
  '.mmc-about-hero-copy',
  '.mmc-float-card',
  '.mmc-float-stack',
  '.mmc-float-pill',
  '.mmc-c10-tools',
  '.mmc-c10-tabs-wrap',
  '.mmc-notfound > *',
  '.page-hero',
  '.mmc-ca-hero-inner',
  '.mmc-ca-section .container > *',
  '.mmc-pred-section .container > *',
  '.mmc-compare-page .container > *',
].join(',');

function shouldSkip(el) {
  if (!el || el.classList.contains('mmc-reveal') || el.hasAttribute('data-mmc-flow')) return true;
  if (el.closest('.mmc-reveal')) return true;
  if (el.closest('.mmc-hero, .mmc-navbar, .mmc-footer, .mmc-no-flow')) return true;
  if (el.matches('input, textarea, select, iframe, svg')) return true;
  return false;
}

function bindParallax(root, observers) {
  const nodes = root.querySelectorAll('[data-mmc-parallax]');
  nodes.forEach((el) => {
    const speed = Number(el.getAttribute('data-mmc-parallax')) || 0.06;
    let visible = false;
    let raf = 0;

    const apply = () => {
      raf = 0;
      if (!visible) return;
      const rect = el.getBoundingClientRect();
      const offset = (window.innerHeight * 0.5 - (rect.top + rect.height * 0.5)) * speed;
      el.style.transform = `translate3d(0, ${offset.toFixed(1)}px, 0)`;
    };

    const onScroll = () => {
      if (!visible || raf) return;
      raf = window.requestAnimationFrame(apply);
    };

    const io = new IntersectionObserver(([entry]) => {
      visible = entry.isIntersecting;
      if (visible) onScroll();
    }, { rootMargin: '120px 0px' });

    io.observe(el);
    observers.push(io);
    window.addEventListener('scroll', onScroll, { passive: true });
    observers.push({ disconnect() { window.removeEventListener('scroll', onScroll); if (raf) cancelAnimationFrame(raf); } });
  });
}

export function bindScrollFlow(root) {
  const observers = [];
  if (!root) return () => {};

  if (prefersReducedMotion()) {
    root.querySelectorAll(SELECTOR).forEach((el) => {
      el.classList.add('mmc-reveal', 'is-in', 'is-ready');
    });
    return () => {};
  }

  const found = Array.from(root.querySelectorAll(SELECTOR)).filter((el) => !shouldSkip(el));
  const targets = found.filter((el) => !found.some((other) => other !== el && other.contains(el)));

  const groups = new Map();
  targets.forEach((el) => {
    const parent = el.parentElement;
    if (!groups.has(parent)) groups.set(parent, []);
    groups.get(parent).push(el);
  });

  groups.forEach((els) => {
    els.forEach((el, index) => {
      const variant = inferRevealVariant(el);
      el.setAttribute('data-mmc-flow', variant);
      el.classList.add('mmc-reveal', `mmc-reveal--${variant}`);
      el.style.setProperty('--mmc-reveal-delay', `${Math.min(index, 5) * 65}ms`);

      const io = new IntersectionObserver(([entry]) => {
        if (!entry.isIntersecting) return;
        el.classList.add('is-in');
        window.setTimeout(() => el.classList.add('is-ready'), 620 + index * 65);
        io.disconnect();
      }, { threshold: 0.12, rootMargin: '0px 0px -10% 0px' });

      io.observe(el);
      observers.push(io);
    });
  });

  bindParallax(root, observers);

  return () => observers.forEach((obs) => obs.disconnect());
}
